// Quanti brouillon preparare in una volta. 67 contatti a 25 al giorno
// sono tre giorni: non serve di piu, e rileggerne 25 resta fattibile.
const MAX_PER_RUN = 25;

function testo(prop) {
  if (!prop) return '';
  if (prop.type === 'title')     return (prop.title || []).map(t => t.plain_text).join('');
  if (prop.type === 'rich_text') return (prop.rich_text || []).map(t => t.plain_text).join('');
  if (prop.type === 'select')    return prop.select ? prop.select.name : '';
  if (prop.type === 'email')     return prop.email || '';
  if (prop.type === 'phone_number') return prop.phone_number || '';
  return '';
}

const risposta = $input.first().json || {};
const pagine = risposta.results || [];

const prospect = pagine.map(pg => {
  const pr = pg.properties || {};
  return {
    pageId:    pg.id,
    nome:      testo(pr['Nome']),
    email:     testo(pr['Email']),
    settore:   testo(pr['Settore']),
    citta:     testo(pr['Citta']),
    accroche:  testo(pr['Accroche']),
    punteggio: testo(pr['Punteggio IA']),
  };
}).filter(p => p.email && p.nome);

// I migliori per primi: un Alto vale piu di un Medio, a parita si tiene l'ordine.
const peso = { 'Alto': 0, 'Medio': 1, 'Basso': 2 };
prospect.sort((a, b) => (peso[a.punteggio] ?? 3) - (peso[b.punteggio] ?? 3));

const scelti = prospect.slice(0, MAX_PER_RUN);

const sd = $getWorkflowStaticData('global');
sd.bozze = 0;
sd.errori = [];

console.log('Prospect contattabili: ' + prospect.length + ' | bozze da preparare: ' + scelti.length);
return scelti.map(p => ({ json: p }));

// ============================================================
// CONFIGURAZIONE DEL MESSAGGIO
// ============================================================
const FIRMA_NOME  = 'Hatem Chebbi';
const FIRMA_RUOLO = 'Manuvo';
const SITO        = 'https://manuvo.automa-ia.net';
const SIGNUP      = 'https://manuvo.automa-ia.net/signup';
const MIA_EMAIL   = 'info@automa-ia.net';

const p = $input.first().json;

// Oggetto sobrio: niente maiuscole urlanti, niente promesse.
const oggetto = 'Richieste di lavoro a ' + (p.citta || 'Rimini');

// L'accroche salvata in Notion comincia quasi sempre con "Buongiorno".
// Il saluto c'è già sopra, quindi va tolto: due saluti di fila si vedono
// lontano un miglio e fanno sembrare il messaggio scritto da una macchina.
function senzaSaluto(t) {
  return String(t || '')
    .replace(/^\s*(buongiorno|buonasera|buondì|salve)\s*[,.:!]?\s*/i, '')
    .trim();
}

let apertura = senzaSaluto(p.accroche);
if (apertura.length > 10) {
  apertura = apertura.charAt(0).toUpperCase() + apertura.slice(1);
} else {
  // Nessuna accroche utilizzabile: si parte con una frase neutra.
  apertura = 'Le scrivo perché sto cercando artigiani della zona di '
    + (p.citta || 'Rimini') + ' per un servizio che sto lanciando qui.';
}

const corpo = [
  'Buongiorno,',
  '',
  apertura,
  '',
  'Mi chiamo ' + FIRMA_NOME + ' e sto lanciando Manuvo a Rimini e dintorni: i privati '
    + 'pubblicano la loro richiesta, e l\'artigiano vede solo quelle del suo mestiere e '
    + 'della sua zona. L\'iscrizione è gratuita e non c\'è nessuna commissione sul lavoro: '
    + 'si pagano solo i contatti che si decide di sbloccare, e al massimo tre artigiani '
    + 'vedono la stessa richiesta.',
  '',
  'Se vuole dare un\'occhiata: ' + SIGNUP,
  '',
  'Le scrivo all\'indirizzo pubblicato sulla sua scheda Google. Se preferisce non '
    + 'ricevere altri messaggi da parte mia, basta rispondere "no grazie" e non la '
    + 'disturbo più.',
  '',
  'Un saluto,',
  FIRMA_NOME + ' - ' + FIRMA_RUOLO,
  SITO + ' - ' + MIA_EMAIL,
].join('\n');

return [{ json: { ...p, oggetto, corpo } }];

const sd = $getWorkflowStaticData('global');
const p = $('Componi email').first().json;
const esito = $input.first().json || {};

if (esito.object === 'error' || esito.error) {
  sd.errori.push(p.nome + ': Notion non aggiornato');
} else {
  sd.bozze = (sd.bozze || 0) + 1;
}
return [{ json: { nome: p.nome, email: p.email } }];

const sd = $getWorkflowStaticData('global');
const bozze = sd.bozze || 0;
const errori = sd.errori || [];

const messaggio = bozze + ' bozze pronte in Gmail. Rileggile e inviale una per una.'
  + (errori.length ? ' Attenzione: ' + errori.length + ' schede non aggiornate in Notion.' : '');

console.log(messaggio);
if (errori.length) console.log(errori.join('\n'));

return [{ json: { bozze, errori, messaggio } }];
